--- index.html
+++ index.html
@@ -24,4 +24,24 @@
 <div class="overlay hidden" id="dialogOverlay"><div class="modal dialog-modal"><div class="dialog-face" id="dialogFace">🧙🏻‍♀️</div><div class="kicker" id="dialogKicker">ENCUENTRO</div><h2 id="dialogTitle">Maelis</h2><div class="quest-text dialog-text" id="dialogText"></div><div class="modal-actions" id="dialogActions"></div></div></div>
 <div class="overlay hidden" id="inventoryOverlay"><div class="modal"><div class="kicker">EQUIPO Y HALLAZGOS</div><h2>Mochila de viaje</h2><div class="inventory-layout"><div><div class="choice-label">OBJETOS</div><div class="items-grid" id="itemsGrid"></div></div><div><div class="choice-label">DETALLES</div><div class="item-detail" id="itemDetail">Elige un objeto para ver sus propiedades.</div></div></div><div class="choice-label" style="margin-top:13px">ARTEFACTOS EQUIPABLES</div><div class="artifact-row"><div class="artifact-slot" id="artifactSlot">◇</div><div class="artifact-copy" id="artifactCopy"><strong>Espacio de reliquia</strong>Encuentra un artefacto en las profundidades.</div></div><div class="modal-actions"><button class="btn ghost" id="closeInventory">Cerrar · I</button></div></div></div>
 <div class="overlay hidden" id="dungeonOverlay"><div class="modal"><div class="sigil">♜</div><div class="kicker">PUERTA DE LA MAZMORRA</div><h2 id="dungeonTitle">Catacumbas de Raíz</h2><p id="dungeonText">Un desafío espera en las profundidades.</p><div class="modal-actions"><button class="btn ghost" id="dungeonBack">Aún no</button><button class="btn primary" id="dungeonEnter">Descender</button></div></div></div>
 </div></section>
+<aside class="column right"><section class="card right-card"><div class="eyebrow">Cuaderno de viaje</div><ul class="quest-list" id="journalList"><li><b>✧ Habla con Maelis</b><br>El roble antiguo guarda una historia.</li><li>○ Encuentra la entrada de las Catacumbas de Raíz.</li><li>○ Derrota al guardián de la mazmorra.</li></ul></section><section class="card"><div class="eyebrow">Reliquia equipada</div><div class="artifact-row"><div class="artifact-slot" id="miniArtifact">◇</div><div class="artifact-copy" id="miniArtifactText"><strong>Vacío</strong>Explora para encontrar magia.</div></div></section></aside>
+</section><footer class="footer"><span>✦ MUNDO ABIERTO · 96 × 96 SECTORES</span><span class="keys"><span><i class="keycap">E</i> hablar</span><span><i class="keycap">SPACE</i> atacar</span><span><i class="keycap">I</i> mochila</span></span><span>PROGRESO GUARDADO EN ESTE DISPOSITIVO</span></footer></main><div class="toast" id="toast"></div>
+<script>
+(()=>{'use strict';
+const $=id=>document.getElementById(id),canvas=$('gameCanvas'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
+const W=96,H=96,T=8,SW=canvas.width,SH=canvas.height;let started=false,mode='world',keys={},last=0,clock=0,toastTimer,quest=0,dungeonDone=false,chestOpen=false,day=1,selected='🍎',dialogAction=null,artifact=null;
+const hero={name:'Lunaria',role:'Guardiana',color:'#88b978',x:13*T,y:15*T,hp:20,maxHp:20,xp:0,gold:12,level:1,damage:1,facing:'down',inventory:{'🍎':3,'🧪':1,'🪙':12,'🌿':0,'🔷':0},attack:0};
+const items=[['🍎','Manzana','Recupera 6 puntos de vida.','heal'],['🧪','Poción solar','Recupera 10 puntos de vida.','heal'],['🪙','Monedas','Brillantes monedas de Lúmina.','misc'],['🌿','Hoja de luna','Una hoja plateada que buscaba Maelis.','quest'],['🔷','Cristal antiguo','Resuena con la magia de las catacumbas.','quest']];
+const npc={x:12*T,y:12*T,name:'Maelis',kind:'npc'},chest={x:17*T,y:22*T},gate={x:48*T,y:31*T},boss={x:58*T,y:51*T,hp:14,max:14,alive:true};
+const mobs=[{x:22*T,y:14*T,hp:3,max:3,type:'slime',alive:true},{x:27*T,y:21*T,hp:3,max:3,type:'slime',alive:true},{x:38*T,y:26*T,hp:4,max:4,type:'moth',alive:true},{x:67*T,y:18*T,hp:5,max:5,type:'wolf',alive:true},{x:73*T,y:62*T,hp:6,max:6,type:'wolf',alive:true},{x:30*T,y:66*T,hp:5,max:5,type:'moth',alive:true}];
+const overlayNames=['startOverlay','creatorOverlay','dialogOverlay','inventoryOverlay','dungeonOverlay'];function overlay(name){overlayNames.forEach(k=>$(k).classList.toggle('hidden',k!==name));if(!name)overlayNames.forEach(k=>$(k).classList.add('hidden'))}function toast(s){const t=$('toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
+function rand(x,y){let n=(x*374761393+y*668265263)|0;n=(n^(n>>>13))*1274126177;return((n^(n>>>16))>>>0)/4294967295}function clamp(a,l,h){return Math.max(l,Math.min(h,a))}function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h)}function text(s,x,y,c='#fff'){ctx.fillStyle=c;ctx.font='5px monospace';ctx.fillText(s,x,y)}
+function updateUI(){ $('heroName').textContent=hero.name;$('heroClass').textContent=`${hero.role} · Nv. ${hero.level}`;$('heroAvatar').textContent=hero.role==='Maga'?'🧝🏻‍♀️':hero.role==='Exploradora'?'🏹':'🧝🏻‍♀️';$('hpText').textContent=`${hero.hp} / ${hero.maxHp}`;$('hpBar').style.width=`${100*hero.hp/hero.maxHp}%`;$('xpText').textContent=`${hero.xp} / ${hero.level*20}`;$('xpBar').style.width=`${100*hero.xp/(hero.level*20)}%`;$('goldText').textContent=hero.gold;$('powerText').textContent=hero.damage+(artifact?.power||0);updateQuestUI()}
+function updateQuestUI(){const q=[['El primer susurro','Habla con la sabia Maelis junto al roble antiguo.',`○ ${quest?1:0} / 1 · Maelis`],['Hojas para el invierno','Recoge una hoja de luna en el claro y llévasela a Maelis.',`○ ${hero.inventory['🌿']?1:0} / 1 · Hoja de luna`],['A las Catacumbas','Busca las Catacumbas de Raíz al este del claro.',`○ ${dungeonDone?1:0} / 1 · Entrada`],['El guardián dormido','Derrota al guardián y trae su cristal a Maelis.',`○ ${hero.inventory['🔷']?1:0} / 1 · Cristal`],['Leyenda de Lúmina','El bosque vuelve a estar en paz. Sigue explorando.', '✦ Encargo completado']][Math.min(quest,4)];$('questName').textContent=q[0];$('questText').textContent=q[1];$('questProgress').textContent=q[2];$('journalList').innerHTML=`<li class="${quest>0?'done':''}"><b>${quest>0?'✓':'✧'} ${quest===0?'Habla con Maelis':quest===1?'Lleva la hoja a Maelis':'La historia de Maelis'}</b><br>${quest<2?'El roble antiguo guarda una historia.':'Una promesa entretejida con el bosque.'}</li><li class="${dungeonDone?'done':''}">${dungeonDone?'✓':'○'} Encuentra las Catacumbas de Raíz.</li><li class="${hero.inventory['🔷']?'done':''}">${hero.inventory['🔷']?'✓':'○'} ${hero.inventory['🔷']?'Reliquia recuperada':'Derrota al guardián de la mazmorra.'}</li>`}
