function attack(target){if(target)hitTarget(target);else{const t=nearby();if(t&&(t.kind==='mob'||t.kind==='boss'))hitTarget(t);else{hero.attack=.12;toast('¡Tajo al aire! Acércate a un monstruo.')}}}
function pathTile(x,y){return(x>=10&&x<=14&&y>=10&&y<=28)||(y>=26&&y<=31&&x>=11&&x<=49)||Math.abs(x-(13+(y-12)*.75))<1.6&&y>11&&y<28}
function treeTile(x,y){if(x<1||y<1||x>=W-1||y>=H-1)return false;if(pathTile(x,y)||Math.hypot(x-12,y-12)<4||Math.hypot(x-17,y-22)<2.5||Math.hypot(x-48,y-31)<3)return false;const r=rand(x,y);return r>.975}
function blocked(x,y){if(mode==='dungeon')return x<13||x>SW-13||y<20||y>SH-13;if(x<5||y<5||x>W*T-5||y>H*T-5)return true;const tx=Math.floor(x/T),ty=Math.floor((y+3)/T);if(treeTile(tx,ty))return true;if(tx>=51&&tx<=55&&ty>=17&&ty<=28&&!pathTile(tx,ty))return true;return false}
function drawGround(){const camX=clamp(hero.x-SW/2,0,W*T-SW),camY=clamp(hero.y-SH/2,0,H*T-SH);ctx.save();ctx.translate(-Math.floor(camX),-Math.floor(camY));const x0=Math.floor(camX/T)-1,y0=Math.floor(camY/T)-1;for(let y=y0;y<y0+SH/T+3;y++)for(let x=x0;x<x0+SW/T+3;x++){if(x<0||y<0||x>=W||y>=H)continue;let biome=y>53?'moss':x>62?'autumn':'grass';let base=biome==='moss'?'#41674a':biome==='autumn'?'#687243':'#4b774e';if(x>=51&&x<=55&&y>=17&&y<=28&&!pathTile(x,y))base='#547d81';if(pathTile(x,y))base='#9b8960';rect(x*T,y*T,T,T,base);const r=rand(x,y);if(pathTile(x,y)){if(r>.8)rect(x*T+(r*5|0),y*T+(r*5|0),1,1,'#c4ac75');}else if(base==='#547d81'){rect(x*T+2,y*T+3,3,1,'#78a1a0');}else if(r>.76){rect(x*T+1+(r*5|0),y*T+1+((r*17)%5|0),1,1,biome==='autumn'?'#b39a5a':'#77a45d');}if(!pathTile(x,y)&&r>.87&&r<.88)rect(x*T+4,y*T+5,1,1,'#d7c580');}
for(let y=y0;y<y0+SH/T+3;y++)for(let x=x0;x<x0+SW/T+3;x++)if(treeTile(x,y))drawTree(x*T,y*T);
drawChest(chest.x,chest.y);drawGate(gate.x,gate.y);drawNPC(npc.x,npc.y);mobs.forEach(m=>{if(m.alive)drawMob(m)});if(boss.alive&&Math.hypot(hero.x-boss.x,hero.y-boss.y)<SW)drawBoss(boss.x,boss.y);drawHero();ctx.restore();return{camX,camY}}
function drawTree(x,y){rect(x+2,y+5,5,4,'#293c2b');rect(x+2,y+8,5,2,'#674d35');rect(x+1,y+2,7,5,'#31543a');rect(x+2,y,5,5,rand(x,y)>.5?'#52794a':'#5e8450');rect(x+3,y+1,2,2,'#7c9a56');rect(x+1,y+4,2,2,'#3f693f')}
function drawNPC(x,y){rect(x-3,y-2,7,2,'#263828');rect(x-2,y-7,5,5,'#b7b78a');rect(x-1,y-6,1,1,'#332c27');rect(x+1,y-6,1,1,'#332c27');rect(x-3,y-2,7,5,'#8273a1');rect(x-4,y,2,4,'#6c6088');rect(x+2,y,2,4,'#6c6088');rect(x-2,y+3,2,2,'#393e34');rect(x+1,y+3,2,2,'#393e34');if(Math.hypot(hero.x-x,hero.y-y)<20){rect(x-3,y-14,7,5,'#f2df9e');text('!',x-1,y-10,'#4a452d')}}
function drawChest(x,y){rect(x-4,y-4,9,7,'#483829');rect(x-3,y-3,7,5,chestOpen?'#74552f':'#bd8b43');rect(x-3,y-4,7,2,'#dbb45d');rect(x,y-2,2,3,'#f0d47a');if(Math.hypot(hero.x-x,hero.y-y)<18)text('E',x-1,y-8,'#fff0ad')}
function drawGate(x,y){rect(x-6,y-2,13,7,'#394234');rect(x-5,y-7,11,8,'#332f2c');rect(x-3,y-5,7,6,'#151c18');rect(x-2,y-4,5,5,'#495545');rect(x-4,y-8,9,2,'#798258');if(Math.hypot(hero.x-x,hero.y-y)<22)text('E',x-1,y-10,'#fff0ad')}
function drawMob(m){const x=Math.round(m.x),y=Math.round(m.y);if(m.type==='slime'){rect(x-4,y-2,8,5,'#254a3b');rect(x-3,y-4,6,6,'#77c793');rect(x-2,y-5,4,3,'#a4e1ae');rect(x-2,y-1,1,1,'#243b33');rect(x+1,y-1,1,1,'#243b33');rect(x-4,y+2,8,1,'#4f956b')}else if(m.type==='moth'){rect(x-1,y-3,2,7,'#724d75');rect(x-5,y-3,4,4,'#bd91cb');rect(x+1,y-3,4,4,'#bd91cb');rect(x-4,y-4,2,2,'#eed0a2');rect(x+2,y-4,2,2,'#eed0a2');rect(x-1,y-1,1,1,'#fff')}else{rect(x-4,y-3,8,6,'#75564a');rect(x-3,y-5,6,5,'#987363');rect(x-4,y-6,2,2,'#d1a588');rect(x+2,y-6,2,2,'#d1a588');rect(x-2,y-3,1,1,'#f0b879');rect(x+1,y-3,1,1,'#f0b879')}if(m.hp<m.max){rect(x-4,y-8,8,1,'#342c26');rect(x-4,y-8,Math.max(1,8*m.hp/m.max),1,'#e27f6f')}}
function drawBoss(x,y){rect(x-8,y-5,16,10,'#42303d');rect(x-7,y-9,14,9,'#69444e');rect(x-5,y-11,10,5,'#876057');rect(x-8,y-4,4,6,'#a18158');rect(x+4,y-4,4,6,'#a18158');rect(x-4,y-7,2,2,'#f0c767');rect(x+2,y-7,2,2,'#f0c767');rect(x-7,y+4,5,3,'#453541');rect(x+2,y+4,5,3,'#453541');rect(x-9,y-14,18,2,'#291d24');rect(x-9,y-14,18*boss.hp/boss.max,2,'#e76564');text('GUARDIÁN',x-12,y-16,'#ffe4b2')}
function drawHero(){const x=Math.round(hero.x),y=Math.round(hero.y),bob=Math.floor(clock*8)%2;if(hero.attack>0){rect(x-7,y-8,14,1,'#f5e3a1');rect(x+5,y-7,1,5,'#fff3c4')}rect(x-3,y-2,6,5,'#272d28');rect(x-3,y-6,6,5,hero.color);rect(x-2,y-9,5,4,'#e6c6a0');rect(x-2,y-10,5,2,'#765041');rect(x-1,y-8,1,1,'#30352c');rect(x+1,y-8,1,1,'#30352c');rect(x-4,y-1+bob,2,3,hero.color);rect(x+2,y-1+bob,2,3,hero.color);rect(x-2,y+3,2,2,'#3c3b38');rect(x+1,y+3,2,2,'#3c3b38');rect(x-3,y-6,6,1,'#f3d37e')}

