function drawHero(){const x=Math.round(hero.x),y=Math.round(hero.y),bob=Math.floor(clock*8)%2;if(hero.attack>0){rect(x-7,y-8,14,1,'#f5e3a1');rect(x+5,y-7,1,5,'#fff3c4')}rect(x-3,y-2,6,5,'#272d28');rect(x-3,y-6,6,5,hero.color);rect(x-2,y-9,5,4,'#e6c6a0');rect(x-2,y-10,5,2,'#765041');rect(x-1,y-8,1,1,'#30352c');rect(x+1,y-8,1,1,'#30352c');rect(x-4,y-1+bob,2,3,hero.color);rect(x+2,y-1+bob,2,3,hero.color);rect(x-2,y+3,2,2,'#3c3b38');rect(x+1,y+3,2,2,'#3c3b38');rect(x-3,y-6,6,1,'#f3d37e')}
const dungeonMobs=[{x:65,y:75,hp:3,max:3,type:'slime',alive:true},{x:180,y:92,hp:4,max:4,type:'moth',alive:true}];let worldReturn={x:hero.x,y:hero.y};
function drawDungeon(){rect(0,0,SW,SH,'#25272a');for(let y=8;y<SH;y+=8)for(let x=8;x<SW;x+=8){rect(x,y,7,7,rand(x,y)>.5?'#41413b':'#393b37');if(rand(x,y)<.13)rect(x+3,y+3,1,1,'#64604e')}rect(15,18,SW-30,4,'#746448');rect(15,SH-22,SW-30,5,'#746448');rect(15,18,4,SH-36,'#746448');rect(SW-19,18,4,SH-36,'#746448');rect(105,138,30,15,'#151616');text('SALIDA',108,155,'#e3cf90');text('CATACUMBAS DE RAÍZ',76,14,'#dbc98f');dungeonMobs.forEach(m=>{if(m.alive)drawMob(m)});if(boss.alive)drawBoss(120,51);drawHero();}
function changeMode(next){mode=next;if(next==='dungeon'){worldReturn={x:hero.x,y:hero.y};hero.x=120;hero.y=126;dungeonMobs.forEach(m=>{m.alive=true;m.hp=m.max});boss.hp=boss.max;overlay(null);$('regionTitle').textContent='♜ CATACUMBAS DE RAÍZ';$('locationText').textContent='Catacumbas de Raíz';toast('Has descendido a la mazmorra. ¡Cuidado con el guardián!')}else{hero.x=worldReturn.x;hero.y=worldReturn.y;overlay(null);$('regionTitle').textContent='✧ PRADO DE LUNARIA';$('locationText').textContent='Prado de Lunaria';toast('Has regresado al bosque.')}}
function draw(){if(mode==='world'){drawGround();const tx=Math.floor(hero.x/T),ty=Math.floor(hero.y/T);const region=ty>54?'Bosque de Ámbar':tx>60?'Linde Salvaje':'Prado de Lunaria';$('locationText').textContent=region;$('regionTitle').textContent=`✧ ${region.toUpperCase()}`;const n=nearby();$('interactionHint').style.display=started&&n?'block':'none';if(n){$('interactionHint').textContent=n.kind==='npc'?'E · hablar con Maelis':n.kind==='chest'?'E · abrir cofre':n.kind==='gate'?'E · entrar a mazmorra':'E / ESPACIO · atacar';}}else{drawDungeon();$('interactionHint').style.display=started?'block':'none';$('interactionHint').textContent='E / ESPACIO · atacar · baja hacia la salida';if(hero.y>138&&hero.x>100&&hero.x<140){changeMode('world')}}}
function move(dt){if(!started||overlayNames.some(k=>!$(k).classList.contains('hidden')))return;let dx=(keys.ArrowRight||keys.d||keys.D?1:0)-(keys.ArrowLeft||keys.a||keys.A?1:0),dy=(keys.ArrowDown||keys.s||keys.S?1:0)-(keys.ArrowUp||keys.w||keys.W?1:0);if(!dx&&!dy)return;if(dx&&dy){dx*=.707;dy*=.707}const speed=38*dt,nx=hero.x+dx*speed,ny=hero.y+dy*speed;if(!blocked(nx,hero.y))hero.x=nx;if(!blocked(hero.x,ny))hero.y=ny;if(Math.abs(dx)>Math.abs(dy))hero.facing=dx>0?'right':'left';else hero.facing=dy>0?'down':'up'}
function updateEnemies(dt){if(!started||Object.values(keys).every(v=>!v)){}const pack=mode==='dungeon'?dungeonMobs:mobs;for(const m of pack){if(!m.alive)continue;const d=Math.hypot(hero.x-m.x,hero.y-m.y);if(d<35&&d>8){m.x+=(hero.x-m.x)/d*13*dt;m.y+=(hero.y-m.y)/d*13*dt}if(d<9&&Math.random()<dt*.55){hero.hp=Math.max(0,hero.hp-1);updateUI();if(!hero.hp){hero.hp=hero.maxHp;hero.x=mode==='world'?13*T:120;hero.y=mode==='world'?15*T:126;hero.gold=Math.max(0,hero.gold-5);updateUI();toast('Te han rescatado en el último instante. −5 oro.')}}}}
function saveGame(){try{const data={hero,quest,dungeonDone,chestOpen,bossAlive:boss.alive,bossHp:boss.hp,mobs:mobs.map(m=>({alive:m.alive,hp:m.hp})),mode:'world'};localStorage.setItem('lumina-save',JSON.stringify(data));toast('Aventura guardada en este dispositivo.')}catch{toast('No se pudo guardar la partida.')}}
function loadGame(){try{const d=JSON.parse(localStorage.getItem('lumina-save'));if(!d)return false;Object.assign(hero,d.hero);quest=d.quest||0;dungeonDone=!!d.dungeonDone;chestOpen=!!d.chestOpen;boss.alive=d.bossAlive!==false;boss.hp=d.bossHp||boss.max;if(d.mobs)d.mobs.forEach((v,i)=>{if(mobs[i])Object.assign(mobs[i],v)});if(d.artifact)artifact=d.artifact;started=true;mode='world';updateUI();overlay(null);toast(`¡Bienvenida de vuelta, ${hero.name}!`);return true}catch{return false}}
function resetGame(){hero.name=$('nameInput').value.trim()||'Lunaria';hero.role=document.querySelector('#classChoices .selected').dataset.class;hero.color=document.querySelector('#colorChoices .selected').dataset.color;hero.x=13*T;hero.y=15*T;hero.hp=20;hero.maxHp=20;hero.gold=12;hero.xp=0;hero.level=1;hero.damage=1;hero.inventory={'🍎':3,'🧪':1,'🪙':12,'🌿':0,'🔷':0};quest=0;dungeonDone=false;chestOpen=false;artifact=null;boss.alive=true;boss.hp=boss.max;mobs.forEach(m=>{m.alive=true;m.hp=m.max});started=true;mode='world';updateUI();overlay(null);toast(`¡Comienza tu aventura, ${hero.name}!`)}

